// dwarf planets: JPL Small-Body Database osculating elements (ecliptic J2000): a, e, i, node, arg. perihelion, mean anomaly at epoch, mean motion (deg/day), epoch (JD)
const SBDB={
  ceres:[2.765552595,0.07969229515,10.58802780,80.24862682,73.29421453,274.4193464,0.21430445064843,2461200.5],
  pluto:[39.58862939,0.2518378779,17.14771141,110.2923841,113.7090015,38.68366347,0.003956838955553025,2457588.5],
  eris:[67.93394688,0.4382385348,43.92582795,36.00477044,150.7949236,211.7744343,0.001760247770619088,2461200.5],
  haumea:[43.06029024,0.1944430149,28.20847393,121.7860561,240.6905473,223.2104119,0.003488097731816818,2461200.5],
  makemake:[45.57093317,0.1588889954,29.02785604,79.29483382,297.0922733,169.9379962,0.003203850120050116,2461200.5]};
function kepler(M,e){let E=M+e*Math.sin(M);for(let i=0;i<10;i++){const d=(E-e*Math.sin(E)-M)/(1-e*Math.cos(E));E-=d;if(Math.abs(d)<1e-12)break}return E}
// heliocentric ecliptic J2000 position (au) from a, e, I, node, arg. perihelion, mean anomaly (radians)
function orbitXYZ(a,e,I,O,w,M,out){const E=kepler(M,e);const xp=a*(Math.cos(E)-e),yp=a*Math.sqrt(1-e*e)*Math.sin(E);
  const cO=Math.cos(O),sO=Math.sin(O),cw=Math.cos(w),sw=Math.sin(w),cI=Math.cos(I),sI=Math.sin(I);
  out[0]=(cw*cO-sw*sO*cI)*xp+(-sw*cO-cw*sO*cI)*yp;out[1]=(cw*sO+sw*cO*cI)*xp+(-sw*sO+cw*cO*cI)*yp;out[2]=(sw*sI)*xp+(cw*sI)*yp;return out}
function elemsAt(id,jd){
  if(JPL[id]){const T=(jd-2451545)/36525,[b,r]=JPL[id];const a=b[0]+r[0]*T,e=b[1]+r[1]*T,I=(b[2]+r[2]*T)*DEG,L=(b[3]+r[3]*T)*DEG,vp=(b[4]+r[4]*T)*DEG,O=(b[5]+r[5]*T)*DEG;
    return [a,e,I,O,vp-O,L-vp]}
  const q=SBDB[id];return [q[0],q[1],q[2]*DEG,q[3]*DEG,q[4]*DEG,(q[5]+q[6]*(jd-q[7]))*DEG]}
function helio(id,jd,out){const el=elemsAt(id,jd);return orbitXYZ(el[0],el[1],el[2],el[3],el[4],el[5],out||[0,0,0])}
// the full orbit as a ring of points (au), for drawing
function orbitRing(id,jd,n){const el=elemsAt(id,jd),pts=[];for(let i=0;i<=n;i++){const M=i/n*2*Math.PI;pts.push(orbitXYZ(el[0],el[1],el[2],el[3],el[4],M,[0,0,0]))}return pts}
const ORBIT_IDS=["mercury","venus","earth","mars","jupiter","saturn","uranus","neptune","ceres","pluto","haumea","makemake","eris"];
// ephemeris for one date, cached
let EPH_jd=NaN;const EPH={};ORBIT_IDS.forEach(id=>EPH[id]=[0,0,0]);
function ephem(jd){if(jd===EPH_jd)return EPH;EPH_jd=jd;ORBIT_IDS.forEach(id=>helio(id,jd,EPH[id]));return EPH}
const rOf=p=>Math.hypot(p[0],p[1],p[2]);
// where a planet appears from Earth: geocentric ecliptic longitude and latitude (deg)
function geo(id,jd){const e=helio("earth",jd,[0,0,0]),p=helio(id,jd,[0,0,0]);const dx=p[0]-e[0],dy=p[1]-e[1],dz=p[2]-e[2],d=Math.hypot(dx,dy,dz);
  return {lon:((Math.atan2(dy,dx)/DEG)%360+360)%360,lat:Math.asin(dz/d)/DEG,d}}
function marsRate(days){const a=geo("mars",jdOf(days-.5)).lon,b=geo("mars",jdOf(days+.5)).lon;let d=b-a;if(d>180)d-=360;if(d<-180)d+=360;return d}   // deg per day; negative = retrograde (westward)

// ---------------------------------------------------------------- scale: one mapping for every drawing and the 3D world
// display: distances squeezed (14·√au) and bodies enlarged; dist: distances to scale (1 au = 6 units), bodies enlarged; true: everything to scale
const AUU=6;
const dispR=au=>14*Math.sqrt(Math.max(au,0));
function mapAU(p,scale,out){const r=Math.hypot(p[0],p[1],p[2])||1e-9;const k=scale==="display"?dispR(r)/r:AUU;
  out[0]=p[0]*k;out[1]=p[2]*k;out[2]=-p[1]*k;return out}       // ecliptic (x,y,z) -> three.js (x, z, -y): ecliptic north is up
const sizeDisp=Rkm=>0.5*Math.pow(Rkm/6371,0.45);
function bodySize(Rkm,scale){return scale==="true"?Rkm/AU_KM*AUU:scale==="dist"?sizeDisp(Rkm)*0.35:sizeDisp(Rkm)}

// ---------------------------------------------------------------- bodies (NASA Planetary Fact Sheet, last updated 18 March 2025, unless noted)
