const MS=[[44900,-5.8],[39500,-5.1],[35100,-4.5],[31400,-3.9],[26000,-3.0],[20600,-1.8],[17000,-1.2],[14500,-0.55],[12300,0],[10700,0.5],[9700,0.99],[8600,1.7],[7760,2.23],[7220,2.57],[6550,3.37],[6050,4.25],[5770,4.8],[5480,5.3],[5270,5.78],[4830,6.5],[4440,7.28],[4100,8.16],[3850,8.8],[3660,9.64],[3430,11.15],[3210,12.61],[3060,14.15],[2930,15.3],[2810,16.32],[2680,17.7]];
function msMag(T){if(T>=MS[0][0])return MS[0][1];for(let i=1;i<MS.length;i++){if(T>=MS[i][0]){const [t0,m0]=MS[i-1],[t1,m1]=MS[i];const u=(Math.log(T)-Math.log(t0))/(Math.log(t1)-Math.log(t0));return lerp(m0,m1,u)}}return MS[MS.length-1][1]}
// luminosity on the HR diagram's scale: the exam diagram's rule, 5 magnitudes = 100 times, Sun = +4.83
const lumOfM=M=>Math.pow(10,-0.4*(M-4.83));
const mOfLum=L=>4.83-2.5*Math.log10(L);
// star colour from temperature (an approximate blackbody tint, for drawing only)
function tColor(T){const t=Math.log10(clamp(T,2400,40000));const stops=[[3.38,[255,140,70]],[3.52,[255,178,110]],[3.62,[255,206,150]],[3.70,[255,236,205]],[3.76,[255,248,236]],[3.86,[236,240,255]],[4.0,[205,220,255]],[4.25,[170,196,255]],[4.6,[150,180,255]]];
  let a=stops[0],b=stops[stops.length-1];for(let i=1;i<stops.length;i++){if(t<=stops[i][0]){a=stops[i-1];b=stops[i];break}}const u=clamp((t-a[0])/((b[0]-a[0])||1),0,1);
  const c=a[1].map((v,i)=>Math.round(lerp(v,b[1][i],u)));return "#"+c.map(v=>v.toString(16).padStart(2,"0")).join("")}
function colourWord(T){return T>=30000?"blue":T>=10000?"blue-white":T>=7500?"white":T>=6000?"yellow-white":T>=5200?"yellow":T>=3700?"orange":"red"}
// which part of the HR diagram a point (T, M) sits in
function regionOf(T,M){const ms=msMag(T),d=M-ms;
  if(d>4.5&&T>6000)return "white dwarfs";if(d>4.5)return "below the main sequence";
  if(d>-2.3)return "main sequence";
  if(M<-4)return T<6500?"red supergiants":"supergiants";
  return T<6000?"red giants":"giants"}

