// Planet surfaces are artist's impressions in the right colours and patterns, not maps (Earth's coastlines are simplified).
const NOISE=(()=>{const p=new Uint8Array(512);let seed=1234567;const r=()=>(seed=(seed*16807)%2147483647)/2147483647;
  const q=[...Array(256).keys()];for(let i=255;i>0;i--){const j=Math.floor(r()*(i+1));[q[i],q[j]]=[q[j],q[i]]}for(let i=0;i<512;i++)p[i]=q[i&255];
  const fade=t=>t*t*t*(t*(t*6-15)+10);
  const grad=(h,x,y,z)=>{const u=h<8?x:y,v=h<4?y:(h===12||h===14?x:z);return((h&1)?-u:u)+((h&2)?-v:v)};
  function n3(x,y,z){const X=Math.floor(x)&255,Y=Math.floor(y)&255,Z=Math.floor(z)&255;x-=Math.floor(x);y-=Math.floor(y);z-=Math.floor(z);const u=fade(x),v=fade(y),w=fade(z);
    const A=p[X]+Y,AA=p[A]+Z,AB=p[A+1]+Z,B=p[X+1]+Y,BA=p[B]+Z,BB=p[B+1]+Z;
    return lerp(lerp(lerp(grad(p[AA]&15,x,y,z),grad(p[BA]&15,x-1,y,z),u),lerp(grad(p[AB]&15,x,y-1,z),grad(p[BB]&15,x-1,y-1,z),u),v),
      lerp(lerp(grad(p[AA+1]&15,x,y,z-1),grad(p[BA+1]&15,x-1,y,z-1),u),lerp(grad(p[AB+1]&15,x,y-1,z-1),grad(p[BB+1]&15,x-1,y-1,z-1),u),v),w)}
  function fbm(x,y,z,o=4){let a=0,amp=.5,f=1;for(let i=0;i<o;i++){a+=amp*n3(x*f,y*f,z*f);f*=2.03;amp*=.5}return a}
  return {n3,fbm}})();
const hex2rgb=h=>{const n=parseInt(h.slice(1),16);return [(n>>16)&255,(n>>8)&255,n&255]};
const mixc=(a,b,t)=>[lerp(a[0],b[0],t),lerp(a[1],b[1],t),lerp(a[2],b[2],t)];
// paint an equirectangular texture: fn(lonRad, latRad, x, y, z) -> [r,g,b(,a)]
// returns a job: run(ms) paints rows until the time budget is spent, and returns true when the canvas is finished
function equirect(W,H,fn,alpha){const c=document.createElement("canvas");c.width=W;c.height=H;const g=c.getContext("2d");const im=g.createImageData(W,H),d=im.data;let j=0;
  return {c,run(ms){const t0=performance.now();
    while(j<H){const lat=(0.5-(j+.5)/H)*Math.PI,cl=Math.cos(lat),sl=Math.sin(lat);
      for(let i=0;i<W;i++){const lon=(i+.5)/W*2*Math.PI;const x=cl*Math.cos(lon),z=cl*Math.sin(lon);const v=fn(lon,lat,x,sl,z);const k=(j*W+i)*4;
        d[k]=v[0];d[k+1]=v[1];d[k+2]=v[2];d[k+3]=alpha?(v[3]??255):255}
      j++;if(performance.now()-t0>ms)break}
    if(j>=H){g.putImageData(im,0,0);return true}return false}}}
