// the view from Earth: Mars against real stars (SIMBAD, brighter than magnitude 5); east to the right, as when you face north from Aotearoa
function drawSkyStrip(W,H){const c=150,half=26,X=l=>{let d=((l-c+540)%360)-180;return W/2+d/half*(W/2-16)},Y=b=>H/2+8+(b-3)*9.5;
  let o=`<rect width="${W}" height="${H}" fill="#060A22"/>`;
  SKY.forEach(st=>{const d=((st.lon-c+540)%360)-180;if(Math.abs(d)<half+1&&Math.abs(st.lat-3)<14){const r=clamp(3.2-.5*st.V,.6,3.6);o+=`<circle cx="${X(st.lon).toFixed(1)}" cy="${Y(st.lat).toFixed(1)}" r="${r.toFixed(2)}" fill="${tColor(4600*(1/(0.92*st.bv+1.7)+1/(0.92*st.bv+0.62)))}"/>`}});
  SKYNAMES.forEach(([n,l,b])=>{const d=((l-c+540)%360)-180;if(Math.abs(d)<half-3&&Math.abs(b-3)<12&&Y(b)<H-48&&Y(b)>30)o+=TX(X(l)-5,Y(b)-6,n,{size:9.5,fill:"#AEB9E6",a:"end"})});
  o+=`<line x1="0" x2="${W}" y1="${Y(0)}" y2="${Y(0)}" stroke="#8FA6FF" stroke-opacity=".25" stroke-dasharray="4 4"/>`+TX(W-8,Y(0)-4,"ecliptic",{size:9,fill:"#8FA6FF",a:"end"});
  // Mars's path from 1 Nov 2026 to now, with the first of each month marked
  const pts=[],ticks=[];for(let d=Math.ceil(RETRO0);d<=s.days;d+=1){const g=geo("mars",jdOf(d));pts.push(`${X(g.lon).toFixed(1)},${Y(g.lat).toFixed(1)}`);const dt=dateOf(d);if(dt.getUTCDate()===1)ticks.push([g,dt])}
  if(pts.length>1)o+=`<polyline points="${pts.join(" ")}" fill="none" stroke="#FF8A5C" stroke-width="2"/>`;
  ticks.forEach(([g,dt])=>o+=`<circle cx="${X(g.lon).toFixed(1)}" cy="${Y(g.lat).toFixed(1)}" r="2.5" fill="#FFD9A8"/>`+TX(X(g.lon),Y(g.lat)+15,dt.toLocaleDateString("en-NZ",{month:"short",timeZone:"UTC"}),{size:9,fill:"#FFD9A8",a:"middle"}));
  const g=geo("mars",jdOf(s.days)),r=marsRate(s.days);if(s.days>=RETRO0-30)o+=`<circle cx="${X(g.lon).toFixed(1)}" cy="${Y(g.lat).toFixed(1)}" r="6" fill="#FF6B3D" stroke="#fff" stroke-width="1.5"/>`;
  o+=TX(12,18,"VIEW FROM EARTH: MARS AGAINST THE STARS",{size:10,ls:".05em",fill:"#AEB9E6"})+TX(12,H-24,"← WEST",{size:10,fill:"#AEB9E6"})+TX(W-12,H-24,"EAST →",{size:10,fill:"#AEB9E6",a:"end"});
  o+=TX(W/2,H-24,r<0?"Mars drifting west: retrograde":"Mars drifting east: normal",{size:11,fill:r<0?"#FFD27A":"#DDE4FF",a:"middle"});
  o+=TX(12,H-8,"Facing north from Aotearoa. Stars: SIMBAD, brighter than magnitude 5.",{size:9,fill:"#7F8BBF"});return o}
// two life paths, with the current stage lit
function drawLifeFlow(W,H){const P=PATHS[s.mass],n=P.stages.length,fi=Math.min(n-1,Math.floor(s.lifeU*n));let o=`<rect width="${W}" height="${H}" fill="#0A1030"/>`+TX(14,22,"TWO PATHS, DECIDED BY MASS (NASA)",{size:10,ls:".05em",fill:"#AEB9E6"});
  const rows=[["Less than about 8 × Sun",["nebula","proto","ms","rg","pn","wd"],62],["More than about 8 × Sun",["nebula","proto","ms","rsg","sn","ns"],152]];
  const short={nebula:"Nebula",proto:"Protostar",ms:"Main sequence",rg:"Red giant",pn:"Planetary nebula",wd:"White dwarf",rsg:"Red supergiant",sn:"Supernova",ns:"Neutron star or black hole"};
  rows.forEach(([lab,ks,y],ri)=>{o+=TX(14,y-14,lab,{size:10.5,fill:"#C9D2F2"});const w=(W-28)/ks.length;
    ks.forEach((kk,j)=>{const cur=P.stages[fi];const on=kk===cur||(kk==="ns"&&(cur==="ns"||cur==="bh"))||(kk==="sn"&&cur==="collapse");const inPath=ri===(+s.mass>8?1:0)&&s.mass!=="0.2";
      const x=14+j*w;o+=`<rect x="${x.toFixed(1)}" y="${y}" width="${(w-6).toFixed(1)}" height="44" rx="10" fill="${on?"#FFD68C":inPath?"#1E2B66":"#121A44"}" stroke="${inPath?"#8FB6FF":"#2A3566"}"/>`;
      const lines=kk==="ns"?["Neutron star","or black","hole"]:short[kk].split(" ").length>1&&short[kk].length>9?[short[kk].split(" ")[0],short[kk].split(" ").slice(1).join(" ")]:[short[kk]];
      lines.forEach((t,li)=>o+=TX(x+(w-6)/2,y+25+li*11-(lines.length-1)*5.5,t,{size:9,a:"middle",fill:on?"#141C46":"#DDE4FF"}))})});
  if(s.mass==="0.2")o+=TX(14,H-26,"A 0.2 × Sun red dwarf stays on the main sequence for",{size:10,fill:"#FFD68C"})+TX(14,H-11,"trillions of years: none has run out of fuel yet.",{size:10,fill:"#FFD68C"});
  else o+=TX(14,H-26,`${s.mass} × Sun: main sequence for ${P.life}.`,{size:10,fill:"#FFD68C"})+TX(14,H-11,`Ends as a ${P.end}.`,{size:10,fill:"#FFD68C"});return o}

// ================================================================ steps
const SOLC=["play","speed","scale","focus","light"];
const steps=[
 {k:"tour",lab:"Scale and light",cap:"Today's solar system, with every planet where it really is. Tap a world to fly to it. Switch to true distances to see how empty space is, then send a pulse of light from the Sun.",
  speed:1,controls:SOLC,chips:["date","focus","sunDist","light"],
  big:"<b>The big idea:</b> the solar system is mostly empty space. Light is the fastest thing there is, yet sunlight takes about 8 minutes to reach Earth and about 4 hours to reach Neptune. Distances to stars are so huge we measure them in light-years: the distance light travels in a year, about 9.46 trillion km.",
  exam:"A light-year is a distance, not a time: it's how far light travels in one year, about 9.46 trillion km. Sunlight takes about 8 minutes 19 seconds to reach Earth, so we see the Sun as it was 8 minutes ago. The nearest star, Proxima Centauri, is about 4.2 light-years away, so the light we see left it over four years ago.",
  trap:"Calling a light-year a measure of time. It's a distance."},
 {k:"form",lab:"Formation",cap:"About 4.6 billion years ago a cloud of gas and dust collapsed. Press play or drag the time slider: the cloud flattens into a spinning disc, the Sun ignites, and grains clump into planets.",
  speed:1,speedLabel:"illustrative timeline",controls:["play","form"],chips:["stage","frost"],
  big:"<b>The big idea:</b> planets grow by accretion. Grains collide and stick; once a clump is big enough, its gravity pulls in more. Near the hot young Sun only rock and metal stayed solid, so the inner planets are small and rocky. Past the frost line, ice was solid too, so cores grew big enough to pull in gas: the giants.",
  exam:"Gravity made the solar nebula collapse. As it shrank it spun faster and flattened into a protoplanetary disc, with the protosun at the centre. Gravitational potential energy turned into heat, and when the core was hot and dense enough, hydrogen nuclei fused into helium. In the disc, dust collided and stuck together (accretion) to form planetesimals. Inside the frost line only high-melting-point rock and metal could condense, forming the rocky planets. Beyond it, ices condensed too, so larger cores formed and their gravity pulled in hydrogen and helium to make the gas giants. The young Sun's solar wind then cleared leftover gas from the inner system.",
  trap:"Saying the planets formed from material thrown off the Sun. They formed in the disc around the young Sun, from the same cloud."},
 {k:"moons",lab:"Moons and rings",cap:"Moons form in three ways: accretion, capture and collision. Pick a case and watch it replay at the real planet. Rings and dwarf planets are here too.",
  speed:1,speedLabel:"illustrative replay",controls:["play","case","replay"],chips:["theory","evidence"],
  big:"<b>The big idea:</b> a moon's orbit and make-up are clues to how it formed. Moons that grew in a disc (accretion) orbit in the planet's equator plane, the same way it spins. Captured moons are often small, lumpy or orbit backwards. A giant collision explains why our Moon's rocks match Earth's.",
  exam:"The collision theory says a Mars-sized body hit the young Earth and threw molten debris into orbit, which clumped together to form the Moon. Evidence: Moon rocks are very similar to Earth's mantle rocks, even in their oxygen isotopes; the Moon was once covered in a magma ocean; and its rocks have little of the elements that boil off when heated, as you'd expect after a very hot impact. Capture can't easily explain the Moon's large size or Earth-like rocks.",
  trap:"Saying the Moon was captured. Capture fits small, lumpy moons like Phobos and Deimos, or backwards moons like Triton, not our Moon."},
 {k:"retro",lab:"Retrograde motion",cap:"Earth laps Mars about every 26 months. As we overtake it, Mars seems to drift backwards against the stars. These are the real dates: watch the view from Earth below.",
  speed:1,controls:["play","speed","date"],chips:["date","motion","em"],
  big:"<b>The big idea:</b> retrograde motion is how Mars looks from a moving Earth, not how it really moves. Every planet orbits the Sun the same way all the time. (Some things really do go backwards: Venus spins backwards, and Triton orbits Neptune backwards.)",
  exam:"Mars's retrograde motion is apparent, not real. Earth is closer to the Sun and moves faster in its orbit, so about every 26 months it catches up with and overtakes Mars. As it does, our line of sight to Mars swings backwards against the much more distant stars, so Mars seems to move west for a few weeks before moving east again. In 2027 this happens from about 11 January to 2 April.",
  trap:"Saying Mars actually turns around in its orbit. It never does; the loop is an effect of watching from a planet that's overtaking it."},
 {k:"hr",lab:"HR diagram",cap:"Every star is a point on this diagram: temperature along the bottom (hottest on the left), luminosity up the side. Tap a real star to read it, or build your own with the sliders.",
  speed:0,controls:["hrPick","pT","pL"],chips:["star","temp","lum","region"],
  big:"<b>The big idea:</b> a star's place on the HR diagram tells you its temperature and colour, its luminosity, and so its size and life stage. Most stars, including the Sun, sit on the main sequence, fusing hydrogen into helium.",
  exam:"Antares is cool, about 3,700 K, so it's red, yet it's more than 10,000 times as luminous as the Sun. A cool surface gives out less energy per square metre, so to be that luminous Antares must have a huge surface area: it's a red supergiant near the end of its life, fusing helium and heavier elements. Sirius B is hot, about 26,000 K, but very dim, so it must be tiny: a white dwarf.",
  trap:"Reading the temperature axis the wrong way. On an HR diagram temperature increases to the left. And on the magnitude scale, brighter stars have smaller or more negative numbers."},
 {k:"life",lab:"Life cycles",cap:"A star is a tug of war: gravity pulls in, and energy from fusion pushes out. Choose a mass, then play its life and watch which side wins.",
  speed:1,speedLabel:"millions to trillions of years",controls:["play","mass","life","core"],chips:["mass","lstage","fuse","balance"],
  big:"<b>The big idea:</b> mass decides everything. Heavier stars squeeze their cores harder, fuse faster and die sooner. Stars under about 8 times the Sun's mass end as white dwarfs; heavier ones explode as supernovae and leave a neutron star or, for the heaviest, a black hole.",
  exam:"On the main sequence, the outward pressure from energy released by hydrogen fusion balances gravity. When the core runs out of hydrogen, fusion there stops and gravity makes the core contract and heat up until helium nuclei fuse into carbon; the outer layers expand and cool into a red giant. A star of less than about 8 solar masses then sheds its outer layers as a planetary nebula, leaving a white dwarf. A more massive star fuses heavier elements up to iron. Fusing iron releases no energy, so gravity wins: the core collapses and the star explodes as a supernova, leaving a neutron star or a black hole.",
  trap:"Saying stars 'burn' their fuel, or that a very massive star can end as a white dwarf. It's nuclear fusion, not burning, and big stars end as neutron stars or black holes. NZQA's 2025 report flags both."},
 {k:"mag",lab:"Magnitude",cap:"How bright a star looks depends on how much light it gives out and how far away it is. Move every star to the same distance, 10 parsecs, to compare them fairly.",
  speed:0,controls:["magPick","same"],chips:["star","app","abs","ly"],
  big:"<b>The big idea:</b> apparent magnitude is how bright a star looks from Earth. Absolute magnitude is how bright it would look from 10 parsecs (32.6 light-years), so it compares the stars' real light output. Smaller or more negative numbers mean brighter; 5 magnitudes is 100 times the brightness.",
  exam:"Sirius has an apparent magnitude of −1.46 and Antares about +0.9, so Sirius looks brighter from Earth. But Sirius is only 8.6 light-years away and Antares is about 550. Their absolute magnitudes, about +1.4 for Sirius and −5.2 for Antares, compare them at the same distance, and show that Antares gives out far more light. Sirius only looks brighter because it's much closer.",
  trap:"Thinking a bigger magnitude number means brighter. It's the other way round: −1 is brighter than +1."},
 {k:"test",lab:"Test yourself",cap:"Use the controls to answer each one, then press Check. The machine marks you with the same model it runs.",
  speed:1,controls:["play","speed","scale","focus","light","date","pT","pL","magPick","same"],chips:["date","light","motion","region","app","abs"],
  big:"<b>Exam tip:</b> NZQA's HR diagram has temperature along the bottom and both luminosity and absolute magnitude up the side. Read a single value off each scale, not a range, and link every reading to an explanation: fusion, gravity, mass or distance."}];
