Object.entries({tour:["whānau a Tamanuiterā","whetūao","tau aho"],form:["tō ā-papa","whetūao"],moons:["marama"],retro:["Matawhero","whetūao"],hr:["whetū","Takurua","Rehua","Atutahi"],life:["tō ā-papa","whetū","Rehua"],mag:["tau aho","Takurua","Rehua"]}).forEach(([k,a])=>{const st=steps.find(x=>x.k===k);if(st)st.kupu=a});
// step entry: set each step up so it opens on something worth seeing
const calmNow=()=>{try{return matchMedia("(prefers-reduced-motion: reduce)").matches}catch(e){return false}};
const ON={tour:()=>{if(s.speed<3)s.speed=5},form:()=>{s.formU=0;s.playing=!calmNow()},moons:()=>{s.caseU=0;s.playing=!calmNow()},
  retro:()=>{if(s.days<RETRO0||s.days>RETRO1-20)s.days=daysOf(2026,11,20);s.speed=4;s.playing=!calmNow()},life:()=>{s.lifeU=0;s.playing=!calmNow()},mag:()=>{s.same=false},test:()=>{s.region="sol"}};
steps.forEach(st=>{if(ON[st.k])st.onStep=()=>ON[st.k]()});
// sliders: temperature on a log scale
const TLO=Math.log(2500),THI=Math.log(40000);const Tof=v=>Math.exp(TLO+(THI-TLO)*v/1000),Tslider=T=>(Math.log(T)-TLO)/(THI-TLO)*1000;
const stageKey=()=>{const P=PATHS[s.mass],n=P.stages.length;return P.stages[Math.min(n-1,Math.floor(s.lifeU*n))]};
const FOCI=[["all","Whole solar system"],["sun","Sun"],...PLANETS.map(id=>[id,BY[id].n]),["moon","Moon"],["ceres","Ceres"],["pluto","Pluto"],["haumea","Haumea"],["makemake","Makemake"],["eris","Eris"],["kuiper","Kuiper Belt"],...MOONS.filter(m=>m.id!=="moon").map(m=>[m.id,`${m.n} (moon of ${BY[m.p].n})`])];
