function tick(x,dt,st){const k=st.k;
  if(k==="tour"||k==="test"||k==="retro"){s.days+=dt*SPEEDS[s.speed][1];if(k==="retro"&&s.days>=RETRO1){s.days=RETRO1;s.playing=false}}
  else if(k==="form"){s.formU=Math.min(1,s.formU+dt/34);if(s.formU>=1)s.playing=false}
  else if(k==="moons"){s.caseU=Math.min(1,s.caseU+dt/12);if(s.caseU>=1)s.playing=false}
  else if(k==="life"){const n=PATHS[s.mass].stages.length;s.lifeU=Math.min(1,s.lifeU+dt/(n*3.6));if(s.lifeU>=1)s.playing=false}}
function chips(x0,st){const E=ephem(jdOf(s.days));const onMag=st&&(st.k==="mag"||(st.k==="test"&&s.region==="mag"));const fid=s.focus;const fp=E[fid];const c=CBY[s.caseId];const r=marsRate(s.days);const H=SBY[s.hrPick],Mg=SBY[s.magPick];const sk=stageKey(),sg=ST[sk];
  const Mp=mOfLum(s.pL);const la=lightAU();
  return {
   date:["DATE (NZ)",fmtDate(s.days)],
   focus:["LOOKING AT",focusName()],
   sunDist:["FROM THE SUN",fp?`${num(rOf(fp),2)} AU`:fid==="sun"?"–":fid==="kuiper"?"30–50 AU":fid==="all"?"Earth: "+num(rOf(E.earth),3)+" AU":"–"],
   light:["SUNLIGHT TAKES",fp?fmtLight(lightSec(rOf(fp))):fid==="kuiper"?"4–7 hours":"Earth: "+fmtLight(lightSec(rOf(E.earth))),s.lightT0!=null],
   stage:["STAGE",FORM[formStage(s.formU)][1],true],
   frost:["FROST LINE","between Mars and Jupiter"],
   theory:["HOW IT FORMED",c.theory,true],
   evidence:["CLUE",c.ev[0]],
   motion:["MARS SEEMS TO MOVE",r<0?"west: retrograde":"east: normal",r<0],
   em:["EARTH TO MARS",num(geo("mars",jdOf(s.days)).d,2)+" AU"],
   star:["STAR",onMag?Mg.n:H.n],
   temp:["TEMPERATURE",(H.id==="sun"?"5,772":"about "+num(Math.round(H.T/100)*100))+" K"],
   lum:["LUMINOSITY",fmtL(lumOfM(H.M))+" × Sun"],
   region:["YOUR STAR",`${num(Math.round(s.pT/10)*10)} K · ${fmtL(s.pL)} × Sun · ${regionOf(s.pT,Mp)}`,s.pT<5772&&s.pL>1],
   mass:["MASS",s.mass+" × Sun"],
   lstage:["STAGE",sg.n,true],
   fuse:["FUSION",sg.fuse],
   balance:["GRAVITY VS PRESSURE",sg.grav>sg.push*1.3?"gravity winning":sg.push>sg.grav*1.3?"pressure winning":"balanced"],
   app:["APPARENT MAG.",`${Mg.n}: ${fmtMag(Mg.m)}`],
   abs:["ABSOLUTE MAG.",`${Mg.n}: ${fmtMag(Mg.M)}`],
   ly:["LIGHT-YEARS AWAY",Mg.id==="sun"?"8 light-minutes":fmtLy(Mg.ly).replace(" light-years","")]}}
const challenges=[
 {q:"Switch to true distances, send light from the Sun, and fly to Neptune to see how long the light takes to get there.",
  check:()=>s.scale!=="display"&&s.focus==="neptune"&&s.lightT0!=null&&lightAU()>=rOf(ephem(jdOf(s.days)).neptune),
  ok:()=>`Yes: sunlight took ${fmtLight(lightSec(rOf(ephem(jdOf(s.days)).neptune)))} to reach Neptune, ${num(rOf(ephem(jdOf(s.days)).neptune),1)} AU away. Even at the speed of light, that's over four hours.`,
  no:()=>s.scale==="display"?"Not yet: choose True distances on the Scale control first.":s.lightT0==null?"Not yet: press Send light from the Sun.":s.focus!=="neptune"?"Not yet: fly to Neptune.":"Nearly: press play and wait for the light to arrive at Neptune."},
 {q:"Make Mars appear to move backwards (west) against the stars.",
  check:()=>marsRate(s.days)<0,
  ok:()=>`Yes: on ${fmtDate(s.days)} Earth is overtaking Mars, so Mars seems to drift west. It's an effect of our moving viewpoint, not a real change of direction.`,
  no:"Not yet: Mars is moving east. Move the date to when Earth overtakes Mars, early in 2027."},
 {q:"Build a star that is more luminous than the Sun but cooler.",
  check:()=>s.pT<5772&&s.pL>1,
  ok:()=>`Yes: ${num(Math.round(s.pT/10)*10)} K and ${fmtL(s.pL)} times the Sun's luminosity. A cooler surface gives out less light from each square metre, so to be brighter it must be bigger than the Sun. It sits in the ${regionOf(s.pT,mOfLum(s.pL))} part of the diagram.`,
  no:()=>s.pT>=5772?"Not yet: make it cooler than the Sun (5,772 K). Slide the temperature to the right on the diagram.":"Not yet: make it more luminous than the Sun (more than 1 × Sun)."},
 {q:"Pick a star that looks brighter than Antares from Earth but gives out less light.",
  check:()=>{const x=SBY[s.magPick],a=SBY.antares;return x.m<a.m&&x.M>a.M},
  ok:()=>{const x=SBY[s.magPick];return `Yes: ${x.n} looks brighter (apparent ${fmtMag(x.m)} vs +0.91) because it's ${x.id==="sun"?"so close":"closer"}, but its absolute magnitude (${fmtMag(x.M)}) shows it gives out less light than Antares (−5.24).`},
  no:()=>{const x=SBY[s.magPick],a=SBY.antares;return x.id==="antares"?"That's Antares itself. Compare it with another star.":x.m>=a.m?`Not yet: ${x.n} (apparent ${fmtMag(x.m)}) doesn't look brighter than Antares. Smaller magnitude = brighter.`:`Not yet: ${x.n} looks brighter, but its absolute magnitude (${fmtMag(x.M)}) is even more negative than Antares's, so it gives out more light.`}}];

